package com.starhub;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import jakarta.servlet.*;import jakarta.servlet.http.*;
import java.io.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
class EarlyBoundedAdmissionTest {
 record Response(HttpServletResponse http,ByteArrayOutputStream bytes){}
 Response response()throws Exception {HttpServletResponse r=mock(HttpServletResponse.class);var bytes=new ByteArrayOutputStream();when(r.getOutputStream()).thenReturn(new ServletOutputStream(){public void write(int b){bytes.write(b);}public boolean isReady(){return true;}public void setWriteListener(WriteListener l){throw new UnsupportedOperationException();}});doAnswer(i->{bytes.reset();return null;}).when(r).resetBuffer();return new Response(r,bytes);}
 HttpServletRequest request(String action)throws Exception {var r=mock(HttpServletRequest.class);when(r.getMethod()).thenReturn("POST");when(r.getServletPath()).thenReturn("/api/workspace");when(r.getContentType()).thenReturn("application/json");when(r.getHeader("X-Starhub-Client")).thenReturn("web");when(r.getHeader("Origin")).thenReturn("https://starhub.zhongjiehuang.com");when(r.getHeader("X-Starhub-Bounded-Read")).thenReturn("chat-v1");var bytes=new ByteArrayInputStream(("{\"action\":\""+action+"\",\"paginationProtocol\":1}").getBytes(java.nio.charset.StandardCharsets.UTF_8));when(r.getInputStream()).thenReturn(new ServletInputStream(){public int read(){return bytes.read();}public int read(byte[] b,int o,int n){return bytes.read(b,o,n);}public boolean isFinished(){return bytes.available()==0;}public boolean isReady(){return true;}public void setReadListener(ReadListener l){throw new UnsupportedOperationException();}});return r;}
 @Test void thirdReaderRejectsBeforeReadinessAndFailureReleasesSlots()throws Exception {var workers=Executors.newFixedThreadPool(2);var entered=new CountDownLatch(2);var release=new CountDownLatch(1);var probes=new AtomicInteger();BoundedChatRead.FreshConfig config=()->{probes.incrementAndGet();entered.countDown();assertTrue(release.await(3,TimeUnit.SECONDS));throw StorageFailure.unavailable();};try{var a=workers.submit(()->{try{BoundedChatRead.run(request("listChats"),response().http,config);}catch(Exception e){throw new RuntimeException(e);}});var b=workers.submit(()->{try{BoundedChatRead.run(request("listChats"),response().http,config);}catch(Exception e){throw new RuntimeException(e);}});assertTrue(entered.await(3,TimeUnit.SECONDS));var rejected=response();BoundedChatRead.run(request("listChats"),rejected.http,config);verify(rejected.http).setStatus(429);assertEquals("NOT_STARTED",ModelGateway.JSON.readTree(rejected.bytes.toByteArray()).path("operationState").asText());assertEquals(2,probes.get());release.countDown();a.get(3,TimeUnit.SECONDS);b.get(3,TimeUnit.SECONDS);var later=response();BoundedChatRead.run(request("listChats"),later.http,()->{probes.incrementAndGet();throw StorageFailure.unavailable();});assertEquals(3,probes.get());verify(later.http).setStatus(503);}finally{release.countDown();workers.shutdown();assertTrue(workers.awaitTermination(3,TimeUnit.SECONDS));}}
 @Test void spoofedMutationNeverReachesReadinessOrSqlAndPermitReturns()throws Exception {var probes=new AtomicInteger();var rejected=response();BoundedChatRead.run(request("deleteFile"),rejected.http,()->{probes.incrementAndGet();throw StorageFailure.unavailable();});verify(rejected.http).setStatus(400);assertEquals(0,probes.get());var later=response();BoundedChatRead.run(request("listChats"),later.http,()->{probes.incrementAndGet();throw StorageFailure.unavailable();});assertEquals(1,probes.get());verify(later.http).setStatus(503);}
}
